<?php require __DIR__.'/app/bootstrap.php';$u=require_user();$iid=(int)($_GET['invoice']??0);$q=db()->prepare('SELECT * FROM invoices WHERE id=? AND user_id=?');$q->execute([$iid,$u['id']]);$i=$q->fetch();if(!$i){http_response_code(404);die('Invoice not found.');}try{$p=mollie_payment_for_invoice($iid);$url=$p['_links']['checkout']['href']??'';if(!$url)throw new RuntimeException('Mollie did not return a checkout URL.');header('Location: '.$url, true, 303);exit;}catch(Throwable $e){http_response_code(500);?><h2>Payment could not be started</h2><p><?=e($e->getMessage())?></p><p><a href="/billing.php">Back to billing</a></p><?php }
